css:
.ebook{--bg:#0D0D0D; --panel:#141210; --panel2:#17140f;
  --gold:#D4AF37; --gold-b:#F3DE8E; --gold-d:#A8842A;
  --ink:#FBF7EE; --body:#D9D3C6; --muted:#8F8A7D; --line:rgba(212,175,55,.30);
  --serif:'Cormorant Garamond',Georgia,serif;
  --disp:'Montserrat','Segoe UI',sans-serif;
  --text:'Inter','Segoe UI',sans-serif;
  --red:#c25b5b; --grn:#4fae86;}
.ebook, .ebook *{box-sizing:border-box}
.ebook,.ebook{margin:0;padding:0;background:#050505;color:var(--body);font-family:var(--text);-webkit-font-smoothing:antialiased}
.ebook .book{display:flex;flex-direction:column;align-items:center;gap:26px;padding:34px 14px 60px}
.ebook .page{position:relative;width:794px;height:1123px;background:var(--bg);overflow:hidden;
  box-shadow:0 30px 80px rgba(0,0,0,.65);border:1px solid rgba(212,175,55,.10);
  padding:48px 56px;display:flex;flex-direction:column}
.ebook .page::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(120% 60% at 50% -8%, rgba(212,175,55,.10), transparent 60%),
   radial-gradient(90% 50% at 110% 108%, rgba(212,175,55,.06), transparent 60%)}
.ebook .mi{width:1em;height:1em;display:block}
.ebook .box-ic{color:var(--gold);display:inline-flex;width:18px;height:18px}
.ebook .box-ic .mi{width:18px;height:18px}
.ebook /* header/footer */
.phead{display:flex;justify-content:space-between;align-items:center;position:relative;z-index:2}
.ebook .brand{display:flex;align-items:center;gap:10px}
.ebook .mark{width:26px;height:26px;border-radius:5px;object-fit:cover;border:1px solid var(--line)}
.ebook .wm{font-family:var(--disp);font-weight:800;font-size:12px;letter-spacing:3px;color:var(--ink)}
.ebook .eyebrow{font-family:var(--disp);font-weight:600;font-size:9px;letter-spacing:3px;color:var(--gold)}
.ebook .hrule{height:1px;background:linear-gradient(90deg,var(--gold),rgba(212,175,55,.05));margin:13px 0 0;position:relative;z-index:2}
.ebook .pbody{flex:1;display:flex;flex-direction:column;position:relative;z-index:2;padding-top:18px;min-height:0}
.ebook .pfoot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid rgba(212,175,55,.14);padding-top:10px;margin-top:8px;position:relative;z-index:2}
.ebook .foot-b{font-family:var(--disp);font-size:8px;letter-spacing:2.4px;color:var(--muted);font-weight:600}
.ebook .foot-n{font-family:var(--disp);font-size:9px;letter-spacing:2px;color:var(--gold);font-weight:700}
.ebook /* strategy head */
.shead{margin-bottom:12px}
.ebook .shead.solo{margin-bottom:16px}
.ebook .s-chapter{font-family:var(--disp);font-weight:700;font-size:9.5px;letter-spacing:3.5px;color:var(--gold);display:block;margin-bottom:5px}
.ebook .s-chapter.center{text-align:center}
.ebook .s-title{font-family:var(--disp);font-weight:800;font-size:27px;line-height:1.05;color:var(--ink);margin:0;letter-spacing:-.3px}
.ebook .s-half{font-family:var(--serif);font-weight:600;font-size:19px;color:var(--gold);font-style:italic}
.ebook .s-sub{font-size:12px;line-height:1.55;color:var(--muted);margin-top:7px;max-width:660px}
.ebook /* top grid: illustration + cards */
.stop{display:grid;grid-template-columns:1.12fr .88fr;gap:18px;align-items:start;margin-bottom:12px}
.ebook .svis{background:linear-gradient(160deg,var(--panel),#0e0c09);border:1px solid var(--line);border-radius:13px;padding:8px;display:flex;align-items:center;justify-content:center;min-height:190px}
.ebook .illo{width:100%;height:auto;display:block}
.ebook .scol{display:flex;flex-direction:column;gap:10px}
.ebook .smid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:12px}
.ebook .smid3{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:6px 0 12px}
.ebook /* q cards */
.qcard{border:1px solid var(--line);border-radius:11px;background:rgba(212,175,55,.035);padding:12px 14px}
.ebook .q-h{display:flex;align-items:center;gap:8px;font-family:var(--disp);font-weight:700;font-size:10.5px;letter-spacing:1px;color:var(--gold);text-transform:uppercase;margin-bottom:7px}
.ebook .q-b{font-size:11.6px;line-height:1.55;color:var(--body)}
.ebook .q-b b{color:var(--ink)}
.ebook ul.mini{list-style:none;margin:0;padding:0}
.ebook ul.mini li{position:relative;padding:2px 0 2px 14px;font-size:11.4px;line-height:1.5;color:var(--body)}
.ebook ul.mini li:before{content:"";position:absolute;left:0;top:9px;width:5px;height:5px;background:var(--gold);border-radius:50%}
.ebook ul.mini b{color:var(--ink)}
.ebook ul.conflist{list-style:none;margin:0;padding:0}
.ebook ul.conflist li{display:flex;align-items:flex-start;gap:8px;font-size:11.4px;line-height:1.45;color:var(--body);padding:3px 0}
.ebook .cbox{width:14px;height:14px;flex:0 0 14px;border:1.4px solid var(--gold);border-radius:4px;margin-top:1px;background:rgba(212,175,55,.06)}
.ebook /* example / boxes */
.example{border:1px solid var(--line);border-radius:11px;background:linear-gradient(180deg,rgba(212,175,55,.05),rgba(212,175,55,0));padding:11px 14px;margin-bottom:10px}
.ebook .ex-tag{display:flex;align-items:center;gap:8px;font-family:var(--disp);font-weight:700;font-size:9.5px;letter-spacing:1.8px;color:var(--gold);text-transform:uppercase;margin-bottom:5px}
.ebook .example p{margin:0;font-size:11.8px;line-height:1.55;color:var(--body)}
.ebook .example b{color:var(--gold-b);font-weight:700}
.ebook .boxrow{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:10px}
.ebook .box{border-radius:11px;padding:11px 14px}
.ebook .box-h{display:flex;align-items:center;gap:8px;font-family:var(--disp);font-weight:700;font-size:10px;letter-spacing:1.2px;text-transform:uppercase;margin-bottom:5px}
.ebook .box p{margin:0;font-size:11.2px;line-height:1.5;color:var(--body)}
.ebook .box b{color:var(--ink)}
.ebook .box.tip{background:rgba(212,175,55,.07);border:1px solid var(--line)}
.ebook .box.tip .box-h{color:var(--gold)}
.ebook .box.warn{background:rgba(194,91,91,.07);border:1px solid rgba(194,91,91,.32)}
.ebook .box.warn .box-h,.ebook .box.warn .box-ic{color:#e08a8a}
.ebook .box.summ{background:linear-gradient(180deg,#141210,#100e0b);border:1px solid var(--line);border-left:3px solid var(--gold)}
.ebook .box.summ .box-h{color:var(--gold)}
.ebook .box.summ p{color:var(--ink);font-weight:500}
.ebook /* ===== COVER ===== */
.cover{align-items:center;justify-content:center;text-align:center;padding:0}
.ebook .cover-glow{position:absolute;inset:0;background:radial-gradient(60% 42% at 50% 30%, rgba(212,175,55,.18), transparent 62%),radial-gradient(50% 30% at 50% 100%, rgba(212,175,55,.10), transparent 60%)}
.ebook .cover-inner{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;padding:54px 60px;width:100%}
.ebook .cover-eyebrow{font-family:var(--disp);font-weight:700;font-size:11px;letter-spacing:5px;color:var(--gold);margin-bottom:24px}
.ebook .cover-logo img{width:270px;height:270px;object-fit:cover;border-radius:16px;border:1px solid var(--line);box-shadow:0 20px 60px rgba(212,175,55,.14)}
.ebook .cover-line{width:120px;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);margin:24px 0}
.ebook .cover-title{font-family:var(--disp);font-weight:900;font-size:44px;line-height:1.02;letter-spacing:-1px;color:var(--ink);margin:0}
.ebook .cover-title span{background:linear-gradient(180deg,var(--gold-b),var(--gold) 55%,var(--gold-d));-webkit-background-clip:text;background-clip:text;color:transparent}
.ebook .cover-sub{font-size:13.5px;line-height:1.7;color:var(--body);margin:18px 0 0;max-width:470px}
.ebook .cover-values{font-family:var(--disp);font-weight:700;font-size:11px;letter-spacing:3px;color:var(--gold)}
.ebook .cover-edition{font-family:var(--disp);font-weight:600;font-size:9px;letter-spacing:3px;color:var(--muted);margin-top:14px}
.ebook /* ===== INDEX ===== */
.idx-list{margin-top:10px}
.ebook .idx-row{display:flex;align-items:baseline;gap:12px;padding:12px 2px;border-bottom:1px solid rgba(212,175,55,.13)}
.ebook .idx-n{font-family:var(--serif);font-weight:700;font-size:22px;color:var(--gold);min-width:44px;text-align:center}
.ebook .idx-t{font-family:var(--disp);font-weight:600;font-size:15px;color:var(--ink)}
.ebook .idx-dots{flex:1;border-bottom:1px dotted rgba(212,175,55,.35);transform:translateY(-4px)}
.ebook .idx-p{font-family:var(--disp);font-weight:700;font-size:13px;color:var(--gold)}
.ebook /* ===== DIVIDER ===== */
.divider-page .pbody{padding-top:0}
.ebook .divider{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;position:relative}
.ebook .dv-badge img{width:70px;height:70px;object-fit:cover;border-radius:13px;border:1px solid var(--line);box-shadow:0 14px 40px rgba(212,175,55,.16);margin-bottom:18px}
.ebook .dv-num{font-family:var(--serif);font-weight:700;font-size:120px;line-height:.8;color:transparent;-webkit-text-stroke:1.5px var(--gold);background:linear-gradient(180deg,rgba(212,175,55,.22),rgba(212,175,55,0));-webkit-background-clip:text;background-clip:text;margin-bottom:6px}
.ebook .dv-title{font-family:var(--disp);font-weight:900;font-size:40px;color:var(--ink);margin:6px 0 0;letter-spacing:-.5px}
.ebook .dv-sub{font-size:13px;line-height:1.6;color:var(--body);max-width:440px;margin-top:14px}
.ebook .dv-line{width:130px;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);margin:22px 0}
.ebook .dv-inside{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;max-width:460px}
.ebook .dv-inside span{font-family:var(--disp);font-weight:600;font-size:10px;letter-spacing:1.5px;color:var(--gold);border:1px solid var(--line);border-radius:20px;padding:5px 12px;text-transform:uppercase;background:rgba(212,175,55,.04)}
.ebook /* ===== TF FUNNEL ===== */
.tf-funnel{display:flex;flex-direction:column;align-items:center;gap:4px;margin:18px 0}
.ebook .tf{border:1px solid var(--line);border-radius:12px;padding:14px 18px;text-align:center;background:linear-gradient(170deg,var(--panel),#0e0c09)}
.ebook .tf1{width:100%}
.ebook .tf2{width:78%}
.ebook .tf3{width:56%}
.ebook .tf-k{font-family:var(--disp);font-weight:800;font-size:12px;letter-spacing:2px;color:var(--gold);display:block}
.ebook .tf-t{font-family:var(--disp);font-weight:700;font-size:15px;color:var(--ink);display:block;margin:3px 0}
.ebook .tf-d{font-size:11px;color:var(--body);line-height:1.4}
.ebook .tf-arrow{color:var(--gold);font-size:14px}
.ebook /* ===== SESSIONS ===== */
.sess-wrap{margin:8px 0 14px}
.ebook .sess-bar{width:100%;height:auto;display:block}
.ebook /* ===== RECIPE ===== */
.recipe{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:10px;margin:20px 0}
.ebook .recipe .ing{font-family:var(--disp);font-weight:700;font-size:13px;color:var(--ink);border:1px solid var(--line);border-radius:10px;padding:12px 16px;background:rgba(212,175,55,.05)}
.ebook .recipe .plus{font-family:var(--disp);font-weight:800;font-size:18px;color:var(--gold)}
.ebook .recipe .equals{font-family:var(--disp);font-weight:900;font-size:26px;color:var(--gold);width:100%;text-align:center;margin:6px 0}
.ebook .recipe .result{font-family:var(--disp);font-weight:900;font-size:20px;letter-spacing:1px;width:100%;text-align:center;background:linear-gradient(180deg,var(--gold-b),var(--gold-d));-webkit-background-clip:text;background-clip:text;color:transparent}
.ebook /* stacked charts */
.stacked{width:100%;display:flex;flex-direction:column;gap:4px}
.ebook .illo-sub{width:100%;height:auto;display:block;border-radius:6px;border:1px solid var(--line)}
.ebook /* ===== PLAN GRID ===== */
.plan-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px 18px;margin:8px 0 16px}
.ebook .plan{display:flex;align-items:center;gap:12px;border:1px solid var(--line);border-radius:11px;padding:12px 14px;background:rgba(212,175,55,.03);position:relative}
.ebook .plan-box{width:20px;height:20px;flex:0 0 20px;border:1.6px solid var(--gold);border-radius:5px;background:rgba(212,175,55,.06)}
.ebook .plan h3{font-family:var(--disp);font-weight:700;font-size:13px;color:var(--ink);margin:0}
.ebook .plan p{font-size:10.6px;line-height:1.4;color:var(--muted);margin:2px 0 0}
.ebook .plan-n{font-family:var(--serif);font-weight:700;font-size:20px;color:rgba(212,175,55,.5);margin-left:auto}
.ebook /* ===== ERRORS ===== */
.err-grid{display:grid;grid-template-columns:1fr;gap:8px 22px;margin:8px 0 14px}
.ebook .err{display:flex;gap:12px;align-items:center;border-bottom:1px solid rgba(212,175,55,.12);padding-bottom:8px}
.ebook .err-n{font-family:var(--serif);font-weight:700;font-size:24px;color:var(--gold);line-height:1;min-width:34px}
.ebook .err-t p{font-size:12.5px;line-height:1.4;color:var(--body);margin:0}
.ebook /* ===== CHEAT ===== */
.cheat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:10px 0}
.ebook .cheat{border:1px solid var(--line);border-radius:12px;padding:13px 14px;background:linear-gradient(170deg,var(--panel),#0e0c09)}
.ebook .cheat-h{font-family:var(--disp);font-weight:800;font-size:11.5px;letter-spacing:1px;color:var(--gold);margin-bottom:8px;text-transform:uppercase}
.ebook .cheat ul{list-style:none;margin:0;padding:0}
.ebook .cheat li{display:flex;align-items:flex-start;gap:7px;font-size:10.8px;line-height:1.4;color:var(--body);padding:3px 0}
.ebook .ck2{color:var(--gold);width:13px;height:13px;flex:0 0 13px;margin-top:1px}
.ebook .ck2 .mi{width:13px;height:13px}
.ebook /* ===== FINAL ===== */
.final-page .pbody{padding-top:14px}
.ebook .final{display:flex;flex-direction:column;align-items:center;text-align:center;flex:1}
.ebook .final-badge img{width:80px;height:80px;object-fit:cover;border-radius:14px;border:1px solid var(--line);box-shadow:0 14px 40px rgba(212,175,55,.16);margin-bottom:12px}
.ebook .final-title{font-family:var(--disp);font-weight:900;font-size:32px;line-height:1.06;color:var(--ink);margin:6px 0 0;letter-spacing:-.4px}
.ebook .final-title span{background:linear-gradient(180deg,var(--gold-b),var(--gold),var(--gold-d));-webkit-background-clip:text;background-clip:text;color:transparent}
.ebook .final-lead{font-size:13px;line-height:1.6;color:var(--body);max-width:520px;margin:14px 0 20px}
.ebook .final-lead b{color:var(--ink)}
.ebook .steps{display:flex;flex-direction:column;gap:11px;width:100%;max-width:560px;margin-bottom:20px}
.ebook .step{display:flex;gap:14px;align-items:center;text-align:left;background:linear-gradient(170deg,var(--panel),#0e0c09);border:1px solid var(--line);border-radius:12px;padding:12px 16px}
.ebook .step-n{font-family:var(--disp);font-weight:800;font-size:17px;color:#0D0D0D;background:linear-gradient(180deg,var(--gold-b),var(--gold-d));width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex:0 0 32px}
.ebook .step h3{font-family:var(--disp);font-weight:700;font-size:14px;color:var(--ink);margin:0 0 2px}
.ebook .step p{font-size:11.4px;line-height:1.4;color:var(--body);margin:0}
.ebook .cta{width:100%;max-width:560px;border:1px solid var(--gold);border-radius:16px;padding:20px;background:radial-gradient(120% 120% at 50% 0%,rgba(212,175,55,.14),rgba(212,175,55,.03));margin-bottom:18px}
.ebook .cta-k{font-family:var(--disp);font-weight:700;font-size:10px;letter-spacing:4px;color:var(--gold);margin-bottom:8px}
.ebook .cta-main{font-family:var(--disp);font-weight:800;font-size:21px;color:var(--ink)}
.ebook .cta-main .hash{background:linear-gradient(180deg,var(--gold-b),var(--gold-d));-webkit-background-clip:text;background-clip:text;color:transparent}
.ebook .cta-sub{font-size:12px;color:var(--body);margin-top:8px}
.ebook .final-quote{font-family:var(--serif);font-style:italic;font-size:20px;color:var(--gold-b);margin-top:auto}
.ebook .final-brand{font-family:var(--disp);font-weight:700;font-size:9px;letter-spacing:3px;color:var(--muted);margin-top:10px}
.ebook /* PRINT */
@page{size:A4;margin:0}
@media print{html,body{background:#fff}
.ebook .book{gap:0;padding:0}
.ebook .page{box-shadow:none;border:none;width:210mm;height:297mm;padding:12mm 14mm;page-break-after:always;break-after:page}
.ebook .page:last-child{page-break-after:auto}
.ebook, .ebook *{-webkit-print-color-adjust:exact;print-color-adjust:exact}
.ebook }

/* wide illustration container */
.svis.wide{min-height:auto;padding:10px 12px;margin-bottom:12px}
.ebook .svis.wide .illo{max-height:270px}
.ebook /* compare (pro vs beginner) */
.compare{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:6px 0 14px}
.ebook .comp{border:1px solid var(--line);border-radius:13px;padding:15px 16px;background:linear-gradient(170deg,var(--panel),#0e0c09)}
.ebook .comp.bad{border-color:rgba(194,91,91,.32)}
.ebook .comp.good{border-color:var(--line);background:linear-gradient(170deg,rgba(212,175,55,.06),#0e0c09)}
.ebook .comp h4{font-family:var(--disp);font-weight:800;font-size:13px;letter-spacing:.5px;margin:0 0 10px;text-transform:uppercase}
.ebook .comp.bad h4{color:#e08a8a}
.ebook .comp.good h4{color:var(--gold)}
.ebook .comp ul{list-style:none;margin:0;padding:0}
.ebook .comp li{position:relative;padding:5px 0 5px 16px;font-size:11.6px;line-height:1.45;color:var(--body);border-bottom:1px solid rgba(212,175,55,.08)}
.ebook .comp li:last-child{border-bottom:none}
.ebook .comp li:before{content:"";position:absolute;left:0;top:11px;width:6px;height:6px;border-radius:50%}
.ebook .comp.bad li:before{background:#c25b5b}
.ebook .comp.good li:before{background:var(--gold)}
.ebook .comp b{color:var(--ink)}
.ebook /* 80/20 bar */
.split8020{margin:10px 0 14px}
.ebook .bar8020{display:flex;height:64px;border-radius:12px;overflow:hidden;border:1px solid var(--line)}
.ebook .fill80{flex:0 0 80%;background:linear-gradient(180deg,rgba(212,175,55,.9),rgba(168,132,42,.9));display:flex;align-items:center;justify-content:center}
.ebook .fill80 span{font-family:var(--disp);font-weight:800;font-size:12px;letter-spacing:1px;color:#0d0d0d}
.ebook .fill20{flex:0 0 20%;background:#1b1712;display:flex;align-items:center;justify-content:center}
.ebook .fill20 span{font-family:var(--disp);font-weight:700;font-size:8.5px;letter-spacing:.5px;color:var(--gold);text-align:center;line-height:1.2}
.ebook /* emotion grid */
.emo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:6px 0 12px}
.ebook .qcard.emo{padding:13px 14px}
.ebook .emo-dot{width:11px;height:11px;border-radius:50%;display:inline-block;margin-right:2px}
.ebook .emo-row{font-size:10.8px;line-height:1.45;color:var(--body);margin-top:5px}
.ebook .emo-row b{color:var(--gold)}
.ebook /* habits grid */
.habits{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:6px 0 14px}
.ebook .habits .qcard{padding:13px 14px}
.ebook .habits .q-b{font-size:11px;line-height:1.5}
.ebook /* journal table */
.jwrap{width:100%}
.ebook .jtable{width:100%;border-collapse:collapse;font-size:11px}
.ebook .jtable th{background:linear-gradient(180deg,rgba(212,175,55,.16),rgba(212,175,55,.04));color:var(--gold);font-family:var(--disp);font-weight:800;font-size:11px;letter-spacing:1px;text-transform:uppercase;padding:9px 12px;text-align:left;border:1px solid var(--line)}
.ebook .jtable td{padding:8px 12px;border:1px solid rgba(212,175,55,.16);vertical-align:top}
.ebook .jtable .jk{color:var(--muted);font-weight:600;width:42%;font-family:var(--disp);font-size:10px;letter-spacing:.5px;text-transform:uppercase}
.ebook .jtable .jv{color:var(--ink);font-weight:500}
.ebook /* index tight for 18 rows */
.idx-list.tight .idx-row{padding:8.5px 2px}
.ebook .idx-list.tight .idx-n{font-size:19px;min-width:40px}
.ebook .idx-list.tight .idx-t{font-size:13.5px}
.ebook /* manifesto */
.mani{display:flex;flex-direction:column;gap:9px;width:100%;max-width:560px;margin:16px 0 18px}
.ebook .mani-line{position:relative;font-family:var(--serif);font-weight:600;font-size:17px;line-height:1.3;color:var(--ink);text-align:center;padding:9px 14px;border:1px solid rgba(212,175,55,.18);border-radius:10px;background:linear-gradient(180deg,rgba(212,175,55,.045),transparent)}
.ebook .mani-line:before{content:"“";position:absolute;left:8px;top:0;color:rgba(212,175,55,.3);font-family:var(--serif);font-size:22px}
.ebook .cta.compact{padding:16px 20px}
