.ebook .mxtable th{background:linear-gradient(180deg,rgba(212,175,55,.16),rgba(212,175,55,.04));color:var(--gold);font-family:var(--disp);font-weight:800;font-size:7.4px;letter-spacing:.2px;text-transform:uppercase;padding:7px 3px;text-align:center;border:1px solid var(--line)}
.ebook .mxtable td{padding:6px 3px;border:1px solid rgba(212,175,55,.14);text-align:center;color:var(--body)}
.ebook .mxtable td.mx-name{font-family:var(--disp);font-weight:800;color:var(--gold-b);text-align:left;padding-left:7px;white-space:nowrap}
.ebook .mxtable td.up{color:#7fceac;font-weight:800}
.ebook .mxtable td.dn{color:#e08a8a;font-weight:800}
.ebook .mxtable td.nu{color:var(--muted)}
.ebook .mxtable td.mx-do{color:#a9dcc4}
.ebook .mxtable td.mx-no{color:#e6a6a6}
.ebook /* cheat table */
.cheat-table td:first-child{color:var(--gold-b);font-weight:700}
.ebook .cheat-table td{font-size:9.5px}
.ebook /* year grid */
.year-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:4px 0}
.ebook .year-block{border:1px solid var(--line);border-radius:12px;background:linear-gradient(170deg,var(--panel),#0e0c09);padding:12px 14px}
.ebook .yb-h{display:flex;align-items:center;gap:8px;font-family:var(--disp);font-weight:800;font-size:12px;color:var(--ink);margin-bottom:8px}
.ebook .fb{font-family:var(--disp);font-weight:800;font-size:7px;padding:2px 7px;border-radius:20px;text-transform:uppercase;letter-spacing:.5px}
.ebook .fb.mens{color:var(--gold);border:1px solid var(--line);background:rgba(212,175,55,.06)}
.ebook .fb.trim{color:#9bc0ea;border:1px solid rgba(111,159,216,.4);background:rgba(111,159,216,.06)}
.ebook .fb.sem{color:#7fceac;border:1px solid rgba(79,174,134,.4);background:rgba(79,174,134,.06)}
.ebook .fb.var{color:var(--muted);border:1px solid rgba(143,138,125,.4)}
.ebook .year-block ul.mini li{font-size:9.6px;padding:2.5px 0 2.5px 13px}
.ebook /* survival flow */
.surv-flow{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:4px 0}
.ebook .surv{border-radius:12px;padding:12px;border:1px solid}
.ebook .surv-t{font-family:var(--serif);font-weight:700;font-size:19px;line-height:1}
.ebook .surv-l{font-family:var(--disp);font-weight:800;font-size:11px;margin:5px 0 5px;letter-spacing:.3px}
.ebook .surv-b{font-size:9.4px;line-height:1.38;color:var(--body)}
.ebook .surv.g1,.ebook .surv.g2,.ebook .surv.g3,.ebook .surv.g4{border-color:var(--line);background:linear-gradient(180deg,rgba(212,175,55,.05),transparent)}
.ebook .surv.g1 .surv-t,.ebook .surv.g2 .surv-t,.ebook .surv.g3 .surv-t,.ebook .surv.g4 .surv-t{color:var(--gold)}
.ebook .surv.g1 .surv-l,.ebook .surv.g2 .surv-l,.ebook .surv.g3 .surv-l,.ebook .surv.g4 .surv-l{color:var(--gold-b)}
.ebook .surv.r1,.ebook .surv.r2{border-color:rgba(194,91,91,.4);background:linear-gradient(180deg,rgba(194,91,91,.06),transparent)}
.ebook .surv.r1 .surv-t,.ebook .surv.r2 .surv-t{color:#e08a8a}
.ebook .surv.r1 .surv-l,.ebook .surv.r2 .surv-l{color:#e6a6a6}
.ebook /* glossary */
.glos-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px 18px;margin-top:4px}
.ebook .glos{border-bottom:1px solid rgba(212,175,55,.12);padding:5px 2px}
.ebook .glos-t{font-family:var(--disp);font-weight:800;font-size:10.5px;color:var(--gold)}
.ebook .glos-d{font-size:9.4px;line-height:1.32;color:var(--body);margin-top:1px}
.ebook /* posters */
.poster{display:flex;flex-direction:column;align-items:center;text-align:center;padding:6px 8px}
.ebook .poster-badge{width:58px;height:58px;border-radius:14px;overflow:hidden;border:1px solid var(--line);margin-bottom:12px}
.ebook .poster-badge img{width:100%;height:100%;object-fit:cover}
.ebook .poster-title{font-family:var(--disp);font-weight:800;font-size:30px;line-height:1.05;color:var(--ink);margin:6px 0 18px;letter-spacing:-.5px}
.ebook .poster-title span{color:var(--gold);font-size:20px;display:inline-block;margin-top:4px}
.ebook .pn-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;width:100%;max-width:560px;margin:6px 0 16px}
.ebook .pn-item{display:flex;align-items:center;gap:11px;border:1px solid var(--line);border-radius:9px;background:linear-gradient(180deg,rgba(212,175,55,.045),transparent);padding:9px 13px}
.ebook .pn-n{font-family:var(--serif);font-weight:700;font-size:16px;color:var(--gold);min-width:24px;text-align:left}
.ebook .pn-name{font-family:var(--disp);font-weight:700;font-size:12px;color:var(--ink)}
.ebook .poster-foot{font-size:9px;color:var(--muted);margin:6px 0 14px}
.ebook .hoy-flow{display:flex;flex-direction:column;gap:10px;width:100%;max-width:520px;margin:10px 0 16px}
.ebook .hoy-step{display:flex;align-items:center;gap:14px;border:1px solid var(--line);border-radius:11px;background:linear-gradient(180deg,rgba(212,175,55,.05),transparent);padding:11px 16px;text-align:left}
.ebook .hoy-q{font-family:var(--serif);font-weight:700;font-size:22px;color:var(--gold);min-width:26px}
.ebook .hoy-step b{font-family:var(--disp);font-size:12.5px;color:var(--ink)}
.ebook .hoy-step p{font-size:10px;color:var(--muted);margin:2px 0 0}
.ebook .hoy-rule{font-family:var(--disp);font-weight:800;font-size:13px;color:var(--gold-b);border:1px dashed var(--gold-d);border-radius:10px;padding:11px 20px;margin-bottom:14px}
.ebook /* index two-col */
.idx-two{display:grid;grid-template-columns:1fr 1fr;gap:0 30px}
.ebook /* note box */
.box.note{background:linear-gradient(180deg,rgba(111,159,216,.07),transparent);border:1px solid rgba(111,159,216,.34)}
.ebook .box.note .box-h,.ebook .box.note .box-ic{color:#9bc0ea}
.ebook .svis-inner{width:100%;display:flex;align-items:center;justify-content:center}
.ebook .svis-inner .illo{max-height:250px}
.ebook /* CTA box */
.cta-box{display:flex;gap:14px;align-items:flex-start;border:1.5px solid var(--gold);border-radius:14px;background:linear-gradient(135deg,rgba(212,175,55,.13),rgba(212,175,55,.03));padding:15px 17px;margin:8px 0}
.ebook .cta-ic{flex-shrink:0;width:40px;height:40px;border-radius:10px;background:var(--gold);color:#0D0D0D;display:flex;align-items:center;justify-content:center}
.ebook .cta-ic .mi{width:22px;height:22px}
.ebook .cta-h{font-family:var(--disp);font-weight:800;font-size:9px;letter-spacing:1.5px;color:var(--gold);text-transform:uppercase;margin-bottom:4px}
.ebook .cta-body p{font-size:11px;line-height:1.5;color:var(--body);margin:0 0 8px}
.ebook .cta-link{display:inline-block;font-family:var(--disp);font-weight:800;font-size:12px;color:#0D0D0D;background:var(--gold);padding:7px 16px;border-radius:8px;text-decoration:none;letter-spacing:.3px}
.ebook /* vertical flow (cap2) */
.flow-v{display:flex;flex-direction:column;gap:9px;margin:4px 0}
.ebook .fv-step{display:flex;align-items:center;gap:14px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(170deg,var(--panel),#0e0c09);padding:12px 16px}
.ebook .fv-n{flex-shrink:0;width:34px;height:34px;border-radius:50%;background:linear-gradient(135deg,var(--gold),var(--gold-d));color:#0D0D0D;font-family:var(--disp);font-weight:800;font-size:15px;display:flex;align-items:center;justify-content:center}
.ebook .fv-body h3{font-family:var(--disp);font-weight:800;font-size:13px;color:var(--ink);margin:0 0 2px}
.ebook .fv-body p{font-size:10px;color:var(--muted);margin:0;line-height:1.35}
.ebook /* dual columns (ok/no) */
.dual{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:4px 0}
.ebook .dual-col{border-radius:13px;padding:13px 15px;border:1px solid}
.ebook .dual-col.ok{border-color:rgba(79,174,134,.4);background:linear-gradient(180deg,rgba(79,174,134,.06),transparent)}
.ebook .dual-col.no{border-color:rgba(194,91,91,.4);background:linear-gradient(180deg,rgba(194,91,91,.06),transparent)}
.ebook .dual-h{font-family:var(--disp);font-weight:800;font-size:12px;margin-bottom:8px;letter-spacing:.3px}
.ebook .dual-col.ok .dual-h{color:#7fceac}
.ebook .dual-col.no .dual-h{color:#e08a8a}
.ebook .dual-col ul.mini li{font-size:10px;padding:3px 0 3px 14px}
.ebook /* rules cards 2x2 (cap5c) */
.rules-cards{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:4px 0}
.ebook .rules-cards .qcard{margin:0}
.ebook /* prep grid (cap6) */
.prep-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:4px 0}
.ebook .prep{display:flex;align-items:flex-start;gap:11px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(170deg,var(--panel),#0e0c09);padding:12px 14px}
.ebook .prep-n{flex-shrink:0;font-family:var(--serif);font-weight:700;font-size:20px;color:var(--gold);min-width:26px}
.ebook .prep h3{font-family:var(--disp);font-weight:800;font-size:11.5px;color:var(--ink);margin:0 0 2px}
.ebook .prep p{font-size:9.5px;color:var(--muted);margin:0;line-height:1.35}
.ebook /* criteria grid (cap9) */
.crit-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:4px 0}
.ebook .crit{display:flex;align-items:flex-start;gap:12px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(170deg,var(--panel),#0e0c09);padding:12px 14px}
.ebook .crit-ic{flex-shrink:0;width:34px;height:34px;border-radius:9px;background:rgba(212,175,55,.1);border:1px solid var(--line);color:var(--gold);display:flex;align-items:center;justify-content:center}
.ebook .crit-ic .mi{width:18px;height:18px}
.ebook .crit h3{font-family:var(--disp);font-weight:800;font-size:11.5px;color:var(--gold);margin:0 0 2px}
.ebook .crit p{font-size:9.5px;color:var(--body);margin:0;line-height:1.35}
.ebook /* FAQ (cap10) */
.faq-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin:4px 0}
.ebook .faq{border:1px solid var(--line);border-radius:12px;background:linear-gradient(170deg,var(--panel),#0e0c09);padding:12px 14px}
.ebook .faq-q{display:flex;align-items:flex-start;gap:8px;font-family:var(--disp);font-weight:800;font-size:11px;color:var(--ink);margin-bottom:6px;line-height:1.2}
.ebook .faq-mark{flex-shrink:0;width:18px;height:18px;border-radius:50%;background:var(--gold);color:#0D0D0D;font-size:11px;display:flex;align-items:center;justify-content:center;font-family:var(--serif)}
.ebook .faq-a{font-size:9.8px;line-height:1.4;color:var(--body)}
.ebook /* check sheet (extras) */
.check-sheet{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin:4px 0}
.ebook .cs-block{border:1px solid var(--line);border-radius:12px;background:linear-gradient(180deg,rgba(212,175,55,.05),transparent);padding:12px 15px}
.ebook .cs-h{font-family:var(--disp);font-weight:800;font-size:12px;color:var(--gold);margin-bottom:8px}
.ebook .cs-block .conflist{margin:0}
.ebook .cs-block .conflist li{font-size:9.8px;padding:4px 0 4px 20px}
.ebook /* template tables */
.tpl-table td{height:22px;color:var(--body)}
.ebook .tpl-table.small td,.ebook .tpl-table.small th{font-size:8.5px;padding:5px 4px}
.ebook .tpl-table td:first-child{color:var(--gold-b);font-weight:700}
.ebook /* compact chapter recap (folded at bottom of last content page) */
.chap-recap-wrap{margin-top:11px}
.ebook .recap{border:1px solid var(--line);border-radius:13px;background:linear-gradient(170deg,rgba(212,175,55,.06),rgba(20,18,16,.6));overflow:hidden}
.ebook .recap-tab{display:flex;align-items:center;gap:7px;font-family:var(--disp);font-weight:800;font-size:9px;letter-spacing:2px;text-transform:uppercase;color:#0D0D0D;background:linear-gradient(90deg,var(--gold),var(--gold-d));padding:6px 14px}
.ebook .recap-tab .box-ic{color:#0D0D0D}
.ebook .recap-tab .mi{width:13px;height:13px}
.ebook .recap-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}
.ebook .rc{background:#100e0b;padding:10px 13px}
.ebook .rc-h{display:flex;align-items:center;gap:6px;font-family:var(--disp);font-weight:800;font-size:9.5px;letter-spacing:.3px;margin-bottom:4px}
.ebook .rc-h .box-ic{width:15px;height:15px}
.ebook .rc-h .mi{width:15px;height:15px}
.ebook .rc p{font-size:9.3px;line-height:1.42;color:var(--body);margin:0}
.ebook .rc-sum{background:linear-gradient(180deg,rgba(212,175,55,.05),#100e0b)}
.ebook .rc-sum .rc-h{color:var(--gold)}
.ebook .rc-sum .rc-h .box-ic{color:var(--gold)}
.ebook .rc-tip .rc-h{color:var(--gold-b)}
.ebook .rc-tip .rc-h .box-ic{color:var(--gold-b)}
.ebook .rc-err{background:linear-gradient(180deg,rgba(194,91,91,.05),#100e0b)}
.ebook .rc-err .rc-h{color:#e08a8a}
.ebook .rc-err .rc-h .box-ic{color:#e08a8a}
.ebook .rc-chk .rc-h{color:#7fceac}
.ebook .rc-chk .rc-h .box-ic{color:#7fceac}
.ebook .rc-list{list-style:none;margin:0;padding:0}
.ebook .rc-list li{position:relative;padding:2px 0 2px 17px;font-size:9px;line-height:1.3;color:var(--body)}
.ebook .rc-list .cbox{position:absolute;left:0;top:3px;width:10px;height:10px;border:1.3px solid var(--gold-d);border-radius:3px}
.ebook /* CTA final page */
.cta-final{max-width:560px;margin:6px auto 14px;text-align:center}
.ebook .cta-final p{font-size:11.5px;line-height:1.55;color:var(--body);margin:0 0 10px}
.ebook .cta-final-link{display:inline-block;font-family:var(--disp);font-weight:800;font-size:15px;color:#0D0D0D;background:var(--gold);padding:11px 26px;border-radius:10px;text-decoration:none;letter-spacing:.3px;margin:6px 0 12px}
.ebook .cta-disc{font-size:9px;color:var(--muted);line-height:1.45;max-width:420px;margin:0 auto;font-style:italic}
.ebook /* roadmap */
.roadmap-wrap{display:flex;justify-content:center;margin:6px 0 10px}
.ebook .roadmap-wrap .illo{max-height:200px;width:100%}
.ebook .road-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:4px 0}
.ebook .rs{border:1px solid var(--line);border-radius:11px;background:linear-gradient(180deg,rgba(212,175,55,.05),transparent);padding:11px 12px}
.ebook .rs-h{font-family:var(--disp);font-weight:800;font-size:11px;color:var(--gold);margin-bottom:4px}
.ebook .rs p{font-size:9px;color:var(--body);margin:0;line-height:1.38}
.ebook /* index two-col */
.idx-two{display:grid;grid-template-columns:1fr 1fr;gap:0 30px}
.ebook /* solo shead spacing when followed by grids */
.shead.solo{margin-bottom:12px}
.ebook /* criteria chips (cta4) */
.crit-chips{display:flex;flex-wrap:wrap;gap:7px;justify-content:center;margin:8px 0}
.ebook .chip{font-family:var(--disp);font-weight:700;font-size:9.5px;color:var(--gold-b);border:1px solid var(--line);background:rgba(212,175,55,.06);border-radius:20px;padding:6px 13px;letter-spacing:.2px}
